<?php use App\Models\Cita; $general=$reporte['general']; ?>
<section class="page-heading"><p class="eyebrow">Administración · CU21</p><h1>Reportes de citas médicas</h1><p class="lead">Estado actual de las citas cuya fecha programada está dentro del período seleccionado. America/La_Paz.</p></section>
<form class="panel reporte-panel reporte-filtros" action="/reportes/citas" method="get" data-reporte-filtros>
<?php foreach(['desde'=>'Fecha inicial','hasta'=>'Fecha final, inclusive'] as $campo=>$label): ?><div class="field-group"><label for="reporte-<?= e($campo) ?>"><?= e($label) ?></label><input id="reporte-<?= e($campo) ?>" type="date" name="<?= e($campo) ?>" value="<?= e($f[$campo]) ?>" required></div><?php endforeach; ?>
<?php foreach(['medico_id'=>['Médico','medicos'],'especialidad_id'=>['Especialidad','especialidades']] as $campo=>[$label,$catalogo]): ?><div class="field-group"><label for="reporte-<?= e($campo) ?>"><?= e($label) ?></label><select id="reporte-<?= e($campo) ?>" name="<?= e($campo) ?>"><option value="">Todos</option><?php foreach($opciones[$catalogo] as $opcion): ?><option value="<?= (int)$opcion['id'] ?>" <?= $f[$campo]===(string)$opcion['id']?'selected':'' ?>><?= e($opcion['nombre']??($opcion['apellidos'].', '.$opcion['nombres'])) ?></option><?php endforeach; ?></select></div><?php endforeach; ?>
<div class="field-group"><label for="reporte-estado">Estado</label><select id="reporte-estado" name="estado"><option value="">Todos los estados</option><?php foreach(Cita::ESTADOS as $valor=>$label): ?><option value="<?= e($valor) ?>" <?= $f['estado']===$valor?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><button class="button" type="submit">Consultar reportes</button><a class="text-link" href="/reportes/citas">Mes actual</a>
</form>
<?php $parametrosExportar=http_build_query(array_intersect_key($f,array_flip(['desde','hasta','medico_id','especialidad_id','estado']))); ?>
<nav class="reporte-exportaciones" aria-label="Descargar reporte con los filtros actuales"><a class="button button-secondary" data-exportar-pdf href="/reportes/citas/exportar/pdf?<?= e($parametrosExportar) ?>">Exportar PDF</a><a class="button button-secondary" data-exportar-csv href="/reportes/citas/exportar/csv?<?= e($parametrosExportar) ?>">Exportar CSV</a></nav>
<p class="notice">Todos los indicadores y tablas usan los mismos filtros. Cada cita se cuenta una vez por su horario vigente, incluso si fue reprogramada. No se cuentan eventos del historial ni fechas de creación o cancelación.</p>
<section class="reporte-indicadores" aria-label="Resumen de citas">
<?php foreach(['total'=>'Total de citas']+Cita::ESTADOS as $estado=>$label): ?><article class="panel reporte-panel"><h2><?= e($label) ?></h2><p class="reporte-cifra" data-reporte-indicador="<?= e($estado) ?>"><?= $general[$estado] ?></p></article><?php endforeach; ?>
</section>
<section class="panel reporte-panel"><h2>Asistencia y situación actual</h2><p>Atendidas: <strong><?= $general['atendida'] ?></strong> · Inasistencias: <strong><?= $general['inasistencia'] ?></strong> · Canceladas: <strong><?= $general['cancelada'] ?></strong>.</p><p>Pendientes: programadas <?= $general['programada'] ?> y confirmadas <?= $general['confirmada'] ?>. Presentes, con atención aún sin finalizar: <?= $general['presente'] ?>.</p><p>Son cifras del estado actual; pueden incluir fechas futuras. No representan tasas clínicas ni un recuento histórico de transiciones.</p></section>
<?php if($general['total']===0): ?><p class="notice" role="status">No hay citas para el período y los filtros seleccionados. Los indicadores son cero.</p><?php endif; ?>
<section class="panel reporte-panel"><h2>Citas por estado</h2><table data-reporte-tabla="estados"><thead><tr><th>Estado actual</th><th>Cantidad</th></tr></thead><tbody><?php foreach(Cita::ESTADOS as $estado=>$label): ?><tr><th scope="row"><?= e($label) ?></th><td><?= $reporte['estados'][$estado] ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th>Total</th><td><?= $general['total'] ?></td></tr></tfoot></table></section>
<?php foreach(['medicos'=>'Citas por médico','especialidades'=>'Citas por especialidad','dias'=>'Distribución diaria'] as $grupo=>$tituloGrupo): ?>
<section class="panel reporte-panel"><h2><?= e($tituloGrupo) ?></h2>
<?php if($grupo==='especialidades'): ?><p>Se usa la especialidad guardada en cada cita. «Sin registrar» agrupa los valores históricos nulos.</p><?php endif; ?>
<?php if($grupo==='dias'): ?><p>Fechas locales de inicio programado. Solo aparecen días con citas; los días omitidos tienen cero citas.</p><?php else: ?><p>Solo aparecen grupos con citas que cumplen los filtros, incluidos registros de catálogo inactivos.</p><?php endif; ?>
<?php if(!$reporte[$grupo]): ?><p role="status">Sin registros para este reporte.</p><?php else: ?>
<div class="table-scroll"><table class="reporte-tabla" data-reporte-tabla="<?= e($grupo) ?>"><thead><tr><th><?= $grupo==='dias'?'Fecha':'Grupo' ?></th><th>Total</th><?php foreach(Cita::ESTADOS as $label): ?><th><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody>
<?php foreach($reporte[$grupo] as $fila): ?><tr><th scope="row"><?= e($fila['etiqueta']) ?></th><td data-label="Total"><?= $fila['total'] ?></td><?php foreach(Cita::ESTADOS as $estado=>$label): ?><td data-label="<?= e($label) ?>"><?= $fila[$estado] ?></td><?php endforeach; ?></tr><?php endforeach; ?>
</tbody><tfoot><tr><th>Total</th><td><?= $general['total'] ?></td><?php foreach(Cita::ESTADOS as $estado=>$label): ?><td><?= $general[$estado] ?></td><?php endforeach; ?></tr></tfoot></table></div><?php endif; ?></section>
<?php endforeach; ?>
